package net.civeira.phylax.features.access.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class RecoverPassEmailTemplateVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property recover pass email template of tenant config ")
  void test_recover_pass_email_template_v_o_builder() {
    Assertions.assertFalse(
        RecoverPassEmailTemplateVO.nullValue().getRecoverPassEmailTemplate().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        RecoverPassEmailTemplateVO.tryFrom(null).getRecoverPassEmailTemplate().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        RecoverPassEmailTemplateVO.from("one").getRecoverPassEmailTemplate().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> RecoverPassEmailTemplateVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", RecoverPassEmailTemplateVO.from("one").toString());
  }
}
